namespace OFC.Infrastructure.Persistence;

public sealed class OFCDbContext(DbContextOptions<OFCDbContext> options) : DbContext(options)
{
    public const string Schema = "ofc";

    public DbSet<User> Users => Set<User>();
    public DbSet<Role> Roles => Set<Role>();
    public DbSet<Permission> Permissions => Set<Permission>();
    public DbSet<UserRole> UserRoles => Set<UserRole>();
    public DbSet<RolePermission> RolePermissions => Set<RolePermission>();
    public DbSet<UserPermission> UserPermissions => Set<UserPermission>();
    public DbSet<UserBranch> UserBranches => Set<UserBranch>();
    public DbSet<Session> Sessions => Set<Session>();
    public DbSet<AuditEntry> AuditEntries => Set<AuditEntry>();
    public DbSet<Organization> Organizations => Set<Organization>();
    public DbSet<Branch> Branches => Set<Branch>();
    public DbSet<PosDevice> PosDevices => Set<PosDevice>();
    public DbSet<BranchSetting> BranchSettings => Set<BranchSetting>();
    public DbSet<Category> Categories => Set<Category>();
    public DbSet<Product> Products => Set<Product>();
    public DbSet<ProductImage> ProductImages => Set<ProductImage>();
    public DbSet<ProductBranchAvailability> ProductBranchAvailability => Set<ProductBranchAvailability>();
    public DbSet<TaxCategory> TaxCategories => Set<TaxCategory>();
    public DbSet<PreparationStation> PreparationStations => Set<PreparationStation>();
    public DbSet<SelectionGroup> SelectionGroups => Set<SelectionGroup>();
    public DbSet<SelectionOption> SelectionOptions => Set<SelectionOption>();
    public DbSet<SelectionGroupBranchAvailability> SelectionGroupBranchAvailability => Set<SelectionGroupBranchAvailability>();
    public DbSet<ProductSelectionGroup> ProductSelectionGroups => Set<ProductSelectionGroup>();
    public DbSet<SalesChannel> SalesChannels => Set<SalesChannel>();
    public DbSet<PriceRule> PriceRules => Set<PriceRule>();
    public DbSet<TaxRule> TaxRules => Set<TaxRule>();
    public DbSet<Promotion> Promotions => Set<Promotion>();
    public DbSet<CatalogVersion> CatalogVersions => Set<CatalogVersion>();
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<OrderLine> OrderLines => Set<OrderLine>();
    public DbSet<OrderStatusHistory> OrderStatusHistory => Set<OrderStatusHistory>();
    public DbSet<PaymentMethod> PaymentMethods => Set<PaymentMethod>();
    public DbSet<Payment> Payments => Set<Payment>();
    public DbSet<PaymentStatusHistory> PaymentStatusHistory => Set<PaymentStatusHistory>();
    public DbSet<FinancialTransaction> FinancialTransactions => Set<FinancialTransaction>();
    public DbSet<CancellationReason> CancellationReasons => Set<CancellationReason>();
    public DbSet<CancellationApprovalThreshold> CancellationApprovalThresholds => Set<CancellationApprovalThreshold>();
    public DbSet<OrderCancellation> OrderCancellations => Set<OrderCancellation>();
    public DbSet<OrderLineVoid> OrderLineVoids => Set<OrderLineVoid>();
    public DbSet<Refund> Refunds => Set<Refund>();
    public DbSet<Shift> Shifts => Set<Shift>();
    public DbSet<ShiftMovement> ShiftMovements => Set<ShiftMovement>();
    public DbSet<ShiftDenomination> ShiftDenominations => Set<ShiftDenomination>();
    public DbSet<PrinterConfiguration> PrinterConfigurations => Set<PrinterConfiguration>();
    public DbSet<PrintTemplate> PrintTemplates => Set<PrintTemplate>();
    public DbSet<PrinterRoute> PrinterRoutes => Set<PrinterRoute>();
    public DbSet<PrintJob> PrintJobs => Set<PrintJob>();
    public DbSet<KitchenTicket> KitchenTickets => Set<KitchenTicket>();
    public DbSet<KitchenTicketItem> KitchenTicketItems => Set<KitchenTicketItem>();
    public DbSet<UnitOfMeasure> UnitsOfMeasure => Set<UnitOfMeasure>();
    public DbSet<UnitConversion> UnitConversions => Set<UnitConversion>();
    public DbSet<InventoryItem> InventoryItems => Set<InventoryItem>();
    public DbSet<RecipeVersion> RecipeVersions => Set<RecipeVersion>();
    public DbSet<RecipeLine> RecipeLines => Set<RecipeLine>();
    public DbSet<InventoryMovement> InventoryMovements => Set<InventoryMovement>();
    public DbSet<SyncOperation> SyncOperations => Set<SyncOperation>();
    public DbSet<SyncState> SyncStates => Set<SyncState>();
    public DbSet<ReportExport> ReportExports => Set<ReportExport>();
    public DbSet<Supplier> Suppliers => Set<Supplier>();
    public DbSet<PurchaseOrder> PurchaseOrders => Set<PurchaseOrder>();
    public DbSet<PurchaseOrderLine> PurchaseOrderLines => Set<PurchaseOrderLine>();
    public DbSet<GoodsReceipt> GoodsReceipts => Set<GoodsReceipt>();
    public DbSet<GoodsReceiptLine> GoodsReceiptLines => Set<GoodsReceiptLine>();
    public DbSet<InventoryCount> InventoryCounts => Set<InventoryCount>();
    public DbSet<InventoryCountLine> InventoryCountLines => Set<InventoryCountLine>();
    public DbSet<StockTransfer> StockTransfers => Set<StockTransfer>();
    public DbSet<StockTransferLine> StockTransferLines => Set<StockTransferLine>();
    public DbSet<WasteRecord> WasteRecords => Set<WasteRecord>();
    public DbSet<QrContext> QrContexts => Set<QrContext>();
    public DbSet<QrOrderApproval> QrOrderApprovals => Set<QrOrderApproval>();
    public DbSet<Customer> Customers => Set<Customer>();
    public DbSet<ExternalOutboxEntry> ExternalOutboxEntries => Set<ExternalOutboxEntry>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.HasDefaultSchema(Schema);
        modelBuilder.Entity<User>(entity => { entity.ToTable("users"); entity.HasIndex(x => x.Email).IsUnique(); entity.HasIndex(x => x.Username).IsUnique(); entity.Property(x => x.Email).HasMaxLength(320); entity.Property(x => x.Username).HasMaxLength(40); entity.Property(x => x.DisplayName).HasMaxLength(160); entity.HasMany(x => x.Roles).WithOne(x => x.User).HasForeignKey(x => x.UserId); entity.HasMany(x => x.Branches).WithOne(x => x.User).HasForeignKey(x => x.UserId); entity.HasMany(x => x.Permissions).WithOne(x => x.User).HasForeignKey(x => x.UserId); });
        modelBuilder.Entity<Role>(entity => { entity.ToTable("roles"); entity.HasIndex(x => x.Name).IsUnique(); entity.Property(x => x.Name).HasMaxLength(100); });
        modelBuilder.Entity<Permission>(entity => { entity.ToTable("permissions"); entity.HasIndex(x => x.Code).IsUnique(); entity.Property(x => x.Code).HasMaxLength(100); entity.Property(x => x.Name).HasMaxLength(160); });
        modelBuilder.Entity<UserRole>(entity => { entity.ToTable("user_roles"); entity.HasKey(x => new { x.UserId, x.RoleId }); entity.HasOne(x => x.Role).WithMany().HasForeignKey(x => x.RoleId); });
        modelBuilder.Entity<RolePermission>(entity => { entity.ToTable("role_permissions"); entity.HasKey(x => new { x.RoleId, x.PermissionId }); entity.HasOne(x => x.Permission).WithMany().HasForeignKey(x => x.PermissionId); });
        modelBuilder.Entity<UserPermission>(entity => { entity.ToTable("user_permissions"); entity.HasKey(x => new { x.UserId, x.PermissionId }); entity.HasIndex(x => x.PermissionId); entity.HasOne(x => x.Permission).WithMany().HasForeignKey(x => x.PermissionId); });
        modelBuilder.Entity<UserBranch>(entity => { entity.ToTable("user_branches"); entity.HasKey(x => new { x.UserId, x.BranchId }); });
        modelBuilder.Entity<Session>(entity => { entity.ToTable("sessions"); entity.HasIndex(x => x.TokenHash).IsUnique(); });
        modelBuilder.Entity<AuditEntry>(entity => { entity.ToTable("audit_entries"); entity.HasIndex(x => x.OccurredAt); entity.Property(x => x.Action).HasMaxLength(100); entity.Property(x => x.EntityType).HasMaxLength(100); entity.Property(x => x.EntityId).HasMaxLength(100); entity.Property(x => x.CorrelationId).HasMaxLength(100); });
        modelBuilder.Entity<Organization>(entity => { entity.ToTable("organizations"); entity.Property(x => x.NameAr).HasMaxLength(160); entity.Property(x => x.NameEn).HasMaxLength(160); });
        modelBuilder.Entity<Branch>(entity => { entity.ToTable("branches"); entity.HasIndex(x => new { x.OrganizationId, x.Code }).IsUnique(); entity.Property(x => x.Code).HasMaxLength(30); entity.Property(x => x.NameAr).HasMaxLength(160); entity.Property(x => x.NameEn).HasMaxLength(160); entity.Property(x => x.TimeZone).HasMaxLength(100); entity.HasMany(x => x.Settings).WithOne().HasForeignKey(x => x.BranchId); });
        modelBuilder.Entity<PosDevice>(entity => { entity.ToTable("pos_devices"); entity.HasIndex(x => x.RegistrationCode).IsUnique(); entity.HasIndex(x => new { x.BranchId, x.Name }).IsUnique(); entity.Property(x => x.Name).HasMaxLength(100); entity.Property(x => x.RegistrationCode).HasMaxLength(100); });
        modelBuilder.Entity<BranchSetting>(entity => { entity.ToTable("branch_settings"); entity.HasIndex(x => new { x.BranchId, x.Key }).IsUnique(); entity.Property(x => x.Key).HasMaxLength(100); entity.Property(x => x.Value).HasMaxLength(2000); });
        modelBuilder.Entity<Category>(entity => { entity.ToTable("categories"); entity.HasIndex(x => x.ParentId); entity.Property(x => x.NameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.ImageUrl).HasMaxLength(CatalogRules.ImageUrlMax); entity.HasOne(x => x.Parent).WithMany(x => x.Children).HasForeignKey(x => x.ParentId).OnDelete(DeleteBehavior.Restrict); });
        // Defense in depth beneath the application-level validation: a future direct DB write or
        // migration/data-fix script can't silently produce a negative price or an inverted selection range.
        modelBuilder.Entity<Product>(entity => { entity.ToTable("products", t => t.HasCheckConstraint("CK_products_base_price_non_negative", "\"BasePrice\" IS NULL OR \"BasePrice\" >= 0")); entity.HasIndex(x => x.Sku).IsUnique(); entity.HasIndex(x => x.Barcode).IsUnique(); entity.HasIndex(x => x.CategoryId); entity.Property(x => x.Sku).HasMaxLength(CatalogRules.SkuMax); entity.Property(x => x.Barcode).HasMaxLength(CatalogRules.BarcodeMax); entity.Property(x => x.NameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.DescriptionAr).HasMaxLength(CatalogRules.DescriptionMax); entity.Property(x => x.DescriptionEn).HasMaxLength(CatalogRules.DescriptionMax); entity.Property(x => x.Type).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.BasePrice).HasPrecision(19, CatalogRules.PricePrecision); entity.HasOne(x => x.Category).WithMany(x => x.Products).HasForeignKey(x => x.CategoryId).OnDelete(DeleteBehavior.Restrict); entity.HasOne(x => x.TaxCategory).WithMany().HasForeignKey(x => x.TaxCategoryId).OnDelete(DeleteBehavior.Restrict); entity.HasOne(x => x.PreparationStation).WithMany().HasForeignKey(x => x.PreparationStationId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<ProductImage>(entity => { entity.ToTable("product_images"); entity.Property(x => x.Url).HasMaxLength(CatalogRules.ImageUrlMax); entity.HasOne<Product>().WithMany(x => x.Images).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Cascade); });
        modelBuilder.Entity<ProductBranchAvailability>(entity => { entity.ToTable("product_branch_availability"); entity.HasKey(x => new { x.ProductId, x.BranchId }); entity.HasIndex(x => x.BranchId); entity.HasOne<Product>().WithMany(x => x.BranchAvailability).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Cascade); });
        modelBuilder.Entity<TaxCategory>(entity => { entity.ToTable("tax_categories"); entity.HasIndex(x => x.Code).IsUnique(); entity.Property(x => x.Code).HasMaxLength(CatalogRules.CodeMax); entity.Property(x => x.NameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.Rate).HasPrecision(9, CatalogRules.PricePrecision); });
        modelBuilder.Entity<PreparationStation>(entity => { entity.ToTable("preparation_stations"); entity.HasIndex(x => x.Code).IsUnique(); entity.Property(x => x.Code).HasMaxLength(CatalogRules.CodeMax); entity.Property(x => x.NameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CatalogRules.NameMax); });
        modelBuilder.Entity<SelectionGroup>(entity => { entity.ToTable("selection_groups", t => t.HasCheckConstraint("CK_selection_groups_min_max", "\"MinSelections\" >= 0 AND \"MaxSelections\" >= 1 AND \"MinSelections\" <= \"MaxSelections\"")); entity.HasIndex(x => new { x.Kind, x.IsActive }); entity.Property(x => x.Kind).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.NameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CatalogRules.NameMax); });
        modelBuilder.Entity<SelectionOption>(entity => { entity.ToTable("selection_options"); entity.HasIndex(x => new { x.SelectionGroupId, x.ProductId }).IsUnique(); entity.Property(x => x.PriceAdjustment).HasPrecision(19, CatalogRules.PricePrecision); entity.HasOne<SelectionGroup>().WithMany(x => x.Options).HasForeignKey(x => x.SelectionGroupId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.Product).WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<SelectionGroupBranchAvailability>(entity => { entity.ToTable("selection_group_branch_availability"); entity.HasKey(x => new { x.SelectionGroupId, x.BranchId }); entity.HasIndex(x => x.BranchId); entity.HasOne<SelectionGroup>().WithMany(x => x.BranchAvailability).HasForeignKey(x => x.SelectionGroupId).OnDelete(DeleteBehavior.Cascade); });
        modelBuilder.Entity<ProductSelectionGroup>(entity => { entity.ToTable("product_selection_groups"); entity.HasKey(x => new { x.ProductId, x.SelectionGroupId }); entity.HasIndex(x => x.SelectionGroupId); entity.HasOne<Product>().WithMany(x => x.SelectionGroups).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Cascade); entity.HasOne(x => x.SelectionGroup).WithMany(x => x.Products).HasForeignKey(x => x.SelectionGroupId).OnDelete(DeleteBehavior.Cascade); });
        modelBuilder.Entity<SalesChannel>(entity => { entity.ToTable("sales_channels"); entity.HasIndex(x => x.Code).IsUnique(); entity.Property(x => x.Code).HasMaxLength(PricingRules.CodeMax); entity.Property(x => x.NameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CatalogRules.NameMax); });
        modelBuilder.Entity<PriceRule>(entity => { entity.ToTable("price_rules"); entity.HasIndex(x => new { x.ProductId, x.BranchId, x.SalesChannelId, x.EffectiveFrom }); entity.HasIndex(x => x.BranchId); entity.HasIndex(x => x.SalesChannelId); entity.Property(x => x.Price).HasPrecision(19, CatalogRules.PricePrecision); entity.HasOne<Product>().WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Cascade); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<SalesChannel>().WithMany().HasForeignKey(x => x.SalesChannelId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<TaxRule>(entity => { entity.ToTable("tax_rules"); entity.HasIndex(x => new { x.TaxCategoryId, x.BranchId, x.EffectiveFrom }); entity.HasIndex(x => x.BranchId); entity.Property(x => x.Rate).HasPrecision(9, CatalogRules.PricePrecision); entity.Property(x => x.CalculationMode).HasConversion<string>().HasMaxLength(20); entity.HasOne<TaxCategory>().WithMany().HasForeignKey(x => x.TaxCategoryId).OnDelete(DeleteBehavior.Cascade); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<Promotion>(entity => { entity.ToTable("promotions"); entity.HasIndex(x => x.Code).IsUnique(); entity.HasIndex(x => new { x.ProductId, x.BranchId, x.SalesChannelId, x.EffectiveFrom }); entity.HasIndex(x => x.BranchId); entity.HasIndex(x => x.SalesChannelId); entity.Property(x => x.Code).HasMaxLength(PricingRules.CodeMax); entity.Property(x => x.NameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.DiscountType).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.DiscountValue).HasPrecision(19, CatalogRules.PricePrecision); entity.HasOne<Product>().WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<SalesChannel>().WithMany().HasForeignKey(x => x.SalesChannelId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<CatalogVersion>(entity => { entity.ToTable("catalog_versions"); entity.HasIndex(x => x.Number).IsUnique(); entity.Property(x => x.Note).HasMaxLength(PricingRules.ReasonMax); entity.HasOne<User>().WithMany().HasForeignKey(x => x.PublishedByUserId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<Order>(entity => { entity.ToTable("orders"); entity.HasIndex(x => new { x.BranchId, x.ClientRequestId }).IsUnique(); entity.HasIndex(x => new { x.BranchId, x.Status, x.CreatedAt }); entity.HasIndex(x => x.CustomerId); entity.Property(x => x.Source).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.Status).HasConversion<string>().HasMaxLength(30); entity.Property(x => x.Note).HasMaxLength(OrderRules.NoteMax); entity.Property(x => x.NetAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.TaxAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.GrossAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.HasMany(x => x.Lines).WithOne().HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Cascade); entity.HasMany(x => x.StatusHistory).WithOne().HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Cascade); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<SalesChannel>().WithMany().HasForeignKey(x => x.SalesChannelId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<User>().WithMany().HasForeignKey(x => x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<Customer>().WithMany().HasForeignKey(x => x.CustomerId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<OrderLine>(entity => { entity.ToTable("order_lines"); entity.HasIndex(x => x.OrderId); entity.Property(x => x.ProductNameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.ProductNameEn).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.Note).HasMaxLength(OrderRules.NoteMax); entity.Property(x => x.SelectionsSnapshot).HasColumnType("jsonb"); entity.Property(x => x.PriceSource).HasMaxLength(30); entity.Property(x => x.TaxCalculationMode).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.UnitListAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.UnitDiscountAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.UnitNetAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.UnitTaxAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.UnitGrossAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.TaxRate).HasPrecision(9, CatalogRules.PricePrecision); entity.HasOne<Product>().WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<OrderStatusHistory>(entity => { entity.ToTable("order_status_history"); entity.HasIndex(x => new { x.OrderId, x.ChangedAt }); entity.Property(x => x.FromStatus).HasConversion<string>().HasMaxLength(30); entity.Property(x => x.ToStatus).HasConversion<string>().HasMaxLength(30); entity.Property(x => x.Note).HasMaxLength(OrderRules.NoteMax); entity.HasOne<User>().WithMany().HasForeignKey(x => x.ChangedByUserId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<PaymentMethod>(entity => { entity.ToTable("payment_methods"); entity.HasIndex(x => new { x.BranchId, x.Code }).IsUnique(); entity.HasIndex(x => new { x.BranchId, x.IsActive, x.SortOrder }); entity.Property(x => x.Code).HasMaxLength(PaymentRules.CodeMax); entity.Property(x => x.NameAr).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CatalogRules.NameMax); entity.Property(x => x.Kind).HasConversion<string>().HasMaxLength(20); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<Payment>(entity => { entity.ToTable("payments"); entity.HasIndex(x => new { x.OrderId, x.ClientRequestId }).IsUnique(); entity.HasIndex(x => new { x.BranchId, x.Status, x.CreatedAt }); entity.Property(x => x.Amount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.TenderedAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.ChangeAmount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.Status).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.ProviderReference).HasMaxLength(PaymentRules.ReferenceMax); entity.HasMany(x => x.StatusHistory).WithOne().HasForeignKey(x => x.PaymentId).OnDelete(DeleteBehavior.Cascade); entity.HasOne<Order>().WithMany().HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<PaymentMethod>().WithMany().HasForeignKey(x => x.PaymentMethodId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<User>().WithMany().HasForeignKey(x => x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<PaymentStatusHistory>(entity => { entity.ToTable("payment_status_history"); entity.HasIndex(x => new { x.PaymentId, x.ChangedAt }); entity.Property(x => x.FromStatus).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.ToStatus).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.Note).HasMaxLength(OrderRules.NoteMax); entity.HasOne<User>().WithMany().HasForeignKey(x => x.ChangedByUserId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<FinancialTransaction>(entity => { entity.ToTable("financial_transactions"); entity.HasIndex(x => x.PaymentId); entity.HasIndex(x => new { x.BranchId, x.CreatedAt }); entity.HasIndex(x => new { x.BranchId, x.ShiftId, x.CreatedAt }); entity.Property(x => x.Type).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.Amount).HasPrecision(19, CatalogRules.PricePrecision); entity.Property(x => x.Reference).HasMaxLength(PaymentRules.ReferenceMax); entity.HasOne<Order>().WithMany().HasForeignKey(x => x.OrderId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<Payment>().WithMany().HasForeignKey(x => x.PaymentId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<PaymentMethod>().WithMany().HasForeignKey(x => x.PaymentMethodId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<User>().WithMany().HasForeignKey(x => x.CreatedByUserId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<FinancialTransaction>().WithMany().HasForeignKey(x => x.ReversalReferenceId).OnDelete(DeleteBehavior.Restrict); entity.HasOne<Shift>().WithMany().HasForeignKey(x => x.ShiftId).OnDelete(DeleteBehavior.SetNull); });
        modelBuilder.Entity<CancellationReason>(entity => { entity.ToTable("cancellation_reasons"); entity.HasIndex(x => new { x.BranchId, x.Code }).IsUnique(); entity.HasIndex(x => new { x.BranchId, x.IsActive, x.SortOrder }); entity.Property(x => x.Code).HasMaxLength(CancellationRules.CodeMax); entity.Property(x => x.NameAr).HasMaxLength(CancellationRules.NameMax); entity.Property(x => x.NameEn).HasMaxLength(CancellationRules.NameMax); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<CancellationApprovalThreshold>(entity => { entity.ToTable("cancellation_approval_thresholds"); entity.HasIndex(x => new { x.BranchId, x.Operation }).IsUnique(); entity.Property(x => x.Operation).HasConversion<string>().HasMaxLength(20); entity.Property(x => x.Amount).HasPrecision(19, CatalogRules.PricePrecision); entity.HasOne<Branch>().WithMany().HasForeignKey(x => x.BranchId).OnDelete(DeleteBehavior.Restrict); });
